window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-90c5147b3316a610"]={"versions": [{"id": "FIG-90c5147b3316a610", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Interaktion zwischen einer Anwendung und dem Zeitsynchronisations-Service (AUTOSAR Adaptive Platform). Es modelliert den Benachrichtigungsmechanismus beim Starten eines Timers über einen Service-Proxy.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt zwei Lebenslinien bzw. Instanzen:</p>\n<ul class=\"fig-list\">\n<li><code>Application</code>: Aufrufende Applikationsinstanz.</li>\n<li><code>TimeBaseServiceProxy</code>: Proxy-Objekt der Zeitsynchronisations-Dienstschnittstelle für eine Zeitbasis.</li>\n</ul>\n<p class=\"fig-p\">Schnittstellenaufruf:</p>\n<ul class=\"fig-list\">\n<li>Synchrone Aufrufnachricht <code>StartTimer(std::chrono::duration&lt;Rep,Period&gt;,uint32_t)</code>.</li>\n<li>Asynchrone Antwortnachricht mit Rückgabetyp <code>std::future&lt;std::uint32-t&gt;</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die <code>Application</code> stößt synchron den Aufruf <code>StartTimer(std::chrono::duration&lt;Rep,Period&gt;,uint32_t)</code> an der Instanz <code>TimeBaseServiceProxy</code> an.</li>\n<li><code>TimeBaseServiceProxy</code> übernimmt den Aufruf (dargestellt über den vertikalen Aktivierungsbalken) und liefert unmittelbar einen <code>std::future&lt;std::uint32-t&gt;</code> per gestrichelter Antwortnachricht an die <code>Application</code> zurück.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Schnittstelle bindet den Timeraufruf an Standard-C++-Konzepte (<code>std::chrono::duration</code> und <code>std::future</code>). Der Rückgabewert <code>std::future</code> ermöglicht der Applikation die asynchrone Abfrage bzw. das Warten auf den Ablauf des konfigurierten Timers. Zu beachten ist die typografische Schreibweise <code>uint32_t</code> im Methodenparameter sowie der fehlerhafte Bezeichner <code>std::uint32-t</code> im Rückgabetyp.</p>"}, {"id": "FIG-81e3096449c79326", "releases": ["R19-03", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Interaktion zwischen einer Anwendung und der Zeitbasis (AUTOSAR Adaptive Platform). Es modelliert den Benachrichtigungsmechanismus beim Starten eines Timers an einer Zeitbasis.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt zwei Lebenslinien bzw. Instanzen:</p>\n<ul class=\"fig-list\">\n<li><code>Application</code>: Aufrufende Applikationsinstanz.</li>\n<li><code>TimeBase</code>: Instanz der Zeitbasis-Schnittstelle.</li>\n</ul>\n<p class=\"fig-p\">Schnittstellenaufruf:</p>\n<ul class=\"fig-list\">\n<li>Synchrone Aufrufnachricht <code>StartTimer(std::chrono::duration&lt;Rep,Period&gt;,std::uint32_t)</code>.</li>\n<li>Antwortnachricht mit Rückgabetyp <code>ara::core::Future&lt;std::uint32_t&gt;</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die <code>Application</code> stößt den Aufruf <code>StartTimer(std::chrono::duration&lt;Rep,Period&gt;,std::uint32_t)</code> an der Instanz <code>TimeBase</code> an.</li>\n<li><code>TimeBase</code> übernimmt den Aufruf im Aktivierungsbalken und liefert eine Instanz von <code>ara::core::Future&lt;std::uint32_t&gt;</code> über die gestrichelte Antwortnachricht an die <code>Application</code> zurück.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Schnittstelle verwendet die AUTOSAR-Adaptive-Standardtypen <code>ara::core::Future</code> sowie C++-Standarddatentypen im Namespace <code>std</code> (<code>std::chrono::duration</code>, <code>std::uint32_t</code>). Über das zurückgegebene <code>ara::core::Future</code> kann die Anwendung asynchron auf die Zeitbenachrichtigung zugreifen.</p>"}], "trans": [{"from": "FIG-90c5147b3316a610", "to": "FIG-81e3096449c79326", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Ziel-Lebenslinie/Entität umbenannt: <code>TimeBaseServiceProxy</code> zu <code>TimeBase</code>.</li>\n<li>Parameter-Typ in Methodenaufruf korrigiert/geändert: <code>StartTimer(std::chrono::duration&lt;Rep,Period&gt;,uint32_t)</code> zu <code>StartTimer(std::chrono::duration&lt;Rep,Period&gt;,std::uint32_t)</code>.</li>\n<li>Rückgabetyp der Antwortnachricht geändert: <code>std::future&lt;std::uint32-t&gt;</code> (mit Bindestrich) zu <code>ara::core::Future&lt;std::uint32_t&gt;</code>.</li>\n</ul>"}]};
